export const defaults=()=>({base:'#d5d7d5',mid:'#9caab9',dark:'#344966',density:25,middle:12,cols:72,rows:12,run:4,seed:2401,style:'vertical'});
export function generate(p,old=[]){let seed=p.seed>>>0;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};const n=p.cols*p.rows, cells=Array(n).fill(0);for(let i=0;i<n;i++)if(old[i]===-1)cells[i]=-1;const available=cells.filter(x=>x!==-1).length;const order=[];const seen=new Set;for(let k=0;k<n*3;k++){let x=Math.floor(rand()*p.cols),y=Math.floor(rand()*p.rows);for(let j=0;j<(p.style==='scatter'?1:p.run);j++){const xx=x+(p.style==='horizontal'?j:0),yy=y+(p.style==='vertical'?j:0),i=yy*p.cols+xx;if(xx<p.cols&&yy<p.rows&&!seen.has(i)&&cells[i]!==-1){seen.add(i);order.push(i)}}}for(let i=0;i<n;i++)if(!seen.has(i)&&cells[i]!==-1)order.push(i);const dark=Math.round(available*p.density/100),mid=Math.min(available-dark,Math.round(available*p.middle/100));order.forEach((i,k)=>cells[i]=k<dark?2:k<dark+mid?1:0);return cells;}
export function parseIntent(text,p){const out={...p},matched=[];for(const [re,style] of [[/横|水平|horizontal/i,'horizontal'],[/縦|竖|垂直|vertical/i,'vertical'],[/ランダム|随机|散|scatter/i,'scatter']])if(re.test(text)){out.style=style;matched.push(style)};for(const [re,color] of [[/紺|蓝|青|navy|ネイビー/i,'#344966'],[/黒|黑|black/i,'#303631'],[/緑|绿|green/i,'#426454'],[/茶|brown|棕/i,'#685044']])if(re.test(text)){out.dark=color;matched.push(color)};const m=text.match(/(?:濃色率|深色比例|深色率|dark)\s*(\d{1,2})\s*[%％]/i);if(m){out.density=Math.min(70,Number(m[1]));matched.push('濃色率 '+out.density+'%')}return{params:out,matched};}
export function validParams(p){return p&&['base','mid','dark'].every(k=>/^#[0-9a-f]{6}$/i.test(p[k]))&&['vertical','horizontal','scatter'].includes(p.style)&&[['cols',12,120],['rows',4,30],['run',1,8],['density',0,70],['middle',0,30],['seed',1,999999]].every(([k,a,b])=>Number.isInteger(p[k])&&p[k]>=a&&p[k]<=b);}
